import { Group, Mesh, Shape, ExtrudeGeometry, CircleGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial, Color, DirectionalLight, PointLight, DoubleSide } from 'three/webgpu';
import { uniform, time, sin, mul, add, color as tslColor } from 'three/tsl';
import { gsap } from 'gsap';

function buildCapsuleShape(w, h, insetStroke = 0) {
  const shape = new Shape();
  const ww = w - insetStroke * 2;
  const hh = h - insetStroke * 2;
  const r = hh / 2;
  shape.moveTo(-ww / 2 + r, -hh / 2);
  shape.lineTo(ww / 2 - r, -hh / 2);
  shape.absarc(ww / 2 - r, 0, r, -Math.PI / 2, Math.PI / 2, false);
  shape.lineTo(-ww / 2 + r, hh / 2);
  shape.absarc(-ww / 2 + r, 0, r, Math.PI / 2, (3 * Math.PI) / 2, false);
  return shape;
}

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'pricing-badge-root';

  const visual = new Group();
  visual.name = 'pricing-badge-visual';
  root.add(visual);

  // ---- geometry dimensions ----
  const W = 1.2;
  const H = 0.42;
  const STROKE = 0.045;

  // ---- main capsule body ----
  const bodyShape = buildCapsuleShape(W, H, 0);
  const bodyGeo = new ExtrudeGeometry(bodyShape, {
    depth: 0.12,
    bevelEnabled: true,
    bevelThickness: 0.018,
    bevelSize: 0.016,
    bevelSegments: 3,
    curveSegments: 16,
  });
  bodyGeo.translate(0, 0, -0.06);

  const bodyMat = new MeshStandardNodeMaterial({
    color: new Color(colors.ink),
    metalness: 0.45,
    roughness: 0.55,
  });

  const body = new Mesh(bodyGeo, bodyMat);
  visual.add(body);

  // ---- accent edge frame (ring) ----
  const outerShape = buildCapsuleShape(W + 0.02, H + 0.02, 0);
  const innerPath = buildCapsuleShape(W + 0.02, H + 0.02, STROKE);
  outerShape.holes.push(innerPath);

  const edgeGeo = new ExtrudeGeometry(outerShape, {
    depth: 0.15,
    bevelEnabled: false,
    curveSegments: 16,
  });
  edgeGeo.translate(0, 0, -0.075);

  const breathe = add(0.94, mul(0.06, sin(mul(time, 1.4))));
  const edgeMat = new MeshStandardNodeMaterial({
    color: new Color(colors.ink),
    metalness: 0.3,
    roughness: 0.4,
    emissive: new Color(colors.accent),
  });
  edgeMat.emissiveNode = mul(tslColor(colors.accent), mul(breathe, 1.9));

  const edge = new Mesh(edgeGeo, edgeMat);
  visual.add(edge);

  // ---- textured grain on main body (async, non-blocking) ----
  let grainTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      grainTexture = tex;
      bodyMat.roughnessMap = tex;
      bodyMat.roughness = 0.65;
      bodyMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---- contact shadow (grounded) ----
  const shadowGeo = new CircleGeometry(0.9, 32);
  const shadowMat = new MeshBasicNodeMaterial({
    color: new Color('#000000'),
    transparent: true,
    opacity: 0.45,
    side: DoubleSide,
    depthWrite: false,
  });
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -H / 2 - 0.28, -0.05);
  visual.add(shadow);

  // ---- local accent rim / edge light ----
  const rimLight = new DirectionalLight(new Color(colors.accent), 0.75);
  rimLight.position.set(-0.6, 0.4, 1.4);
  visual.add(rimLight);

  const edgeGlow = new PointLight(new Color(colors.accent), 0.6, 2.2, 2);
  edgeGlow.position.set(0.7, 0, 0.4);
  visual.add(edgeGlow);

  // ---- initial entrance state ----
  visual.scale.setScalar(0.001);
  visual.position.y = -0.15;

  const timelines = [];

  const entrance = gsap.timeline();
  entrance.to(visual.scale, { x: 1, y: 1, z: 1, duration: 0.7, ease: 'power3.out' });
  entrance.to(visual.position, { y: 0, duration: 0.9, ease: 'power4.out' }, 0);
  timelines.push(entrance);

  // ---- interaction state ----
  let hovered = false;
  let baseY = 0;

  function onPointerEnter() {
    if (hovered) return;
    hovered = true;
    const tl = gsap.timeline();
    tl.to(visual.position, { y: baseY + 0.15, duration: 0.3, ease: 'power2.out' }, 0);
    tl.to(visual.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.3, ease: 'power2.out' }, 0);
    tl.to(edgeGlow, { intensity: 1.1, duration: 0.3, ease: 'power2.out' }, 0);
    timelines.push(tl);
  }

  function onPointerLeave() {
    hovered = false;
    const tl = gsap.timeline();
    tl.to(visual.position, { y: baseY, duration: 0.35, ease: 'power3.out' }, 0);
    tl.to(visual.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0);
    tl.to(edgeGlow, { intensity: 0.6, duration: 0.3, ease: 'power2.out' }, 0);
    timelines.push(tl);
  }

  function onClick() {
    const tl = gsap.timeline();
    tl.to(visual.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
    tl.to(visual.scale, { x: hovered ? 1.04 : 1, y: hovered ? 1.04 : 1, z: hovered ? 1.04 : 1, duration: 0.3, ease: 'power2.out' });
    timelines.push(tl);
    ctx.emit('hub-pricing.select', { id: 'pricing-badge' });
  }

  root.userData.handlers = {
    onPointerEnter,
    onPointerOver: onPointerEnter,
    onPointerLeave,
    onPointerOut: onPointerLeave,
    onClick,
    onPointerDown: onClick,
  };

  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;

    bodyGeo.dispose();
    edgeGeo.dispose();
    shadowGeo.dispose();

    bodyMat.dispose();
    edgeMat.dispose();
    shadowMat.dispose();

    if (grainTexture && grainTexture.dispose) grainTexture.dispose();

    visual.remove(rimLight);
    visual.remove(edgeGlow);

    while (visual.children.length) visual.remove(visual.children[0]);
    while (root.children.length) root.remove(root.children[0]);
  };

  return root;
}
